//! Heap-backed byte tail for `TaskStorage`'s lazy fields.
//!
//! Each lazy variant is assigned a 1-based tag at macro time (see
//! `LAZY_TAG_*` constants). A presence bitmap (`present`) records which tags
//! have a payload stored; the byte buffer holds payloads packed in tag order,
//! each at its own alignment. Per-tag size and alignment are looked up via
//! the `LAZY_SIZE`, `LAZY_ALIGN`, and `LAZY_PADDED_SIZE` tables emitted by
//! the schema.
//!
//! `LazyTail` only manages the byte buffer — dropping individual payloads
//! requires the per-tag drop dispatch generated by the macro. `TaskStorage`
//! implements `Drop` to walk the bitmap, invoke the drop dispatch on each
//! payload, then let `LazyTail`'s field-level drop dealloc the buffer.

use std::{
    alloc::{Layout, alloc, dealloc, handle_alloc_error},
    fmt,
    marker::PhantomData,
    ptr::NonNull,
};

use turbo_tasks::ShrinkToFit;

/// Maximum alignment used for the tail buffer. Must be at least the largest
/// per-tag alignment in `LAZY_ALIGN`. The schema-emitted constant
/// `LAZY_MAX_ALIGN` is asserted equal at construction time.
pub(crate) const TAIL_BUFFER_ALIGN: usize = 8;

/// Owns the byte tail and the presence bitmap.
///
/// Laid out as `(present, len, cap, ptr)` for explicit `#[repr(C)]` so the
/// total fits in 16 B on 64-bit, the same size as the previous
/// `TinyVec<LazyField, _>` slot.
#[repr(C)]
pub(crate) struct LazyTail {
    /// Presence bitmap: bit `tag - 1` is set iff the variant with that tag is
    /// stored in the tail.
    pub(crate) present: u32,
    /// Bytes used in the tail buffer.
    pub(crate) len: u16,
    /// Bytes allocated in the tail buffer.
    pub(crate) cap: u16,
    /// Tail buffer pointer. Dangling when `cap == 0`.
    pub(crate) ptr: NonNull<u8>,
    /// Variance: we conceptually own raw bytes. `PhantomData<*mut u8>` would
    /// prevent the auto-Send/Sync derives; we add explicit `unsafe impl`s
    /// below so the auto-derive on `TaskStorage` continues to work.
    _marker: PhantomData<u8>,
}

// SAFETY: We own a heap allocation of bytes that no one else can observe
// while we hold a unique reference. The bytes are only interpreted through
// our typed methods (each of which carries a SAFETY contract on the caller).
unsafe impl Send for LazyTail {}
unsafe impl Sync for LazyTail {}

impl Default for LazyTail {
    fn default() -> Self {
        Self {
            present: 0,
            len: 0,
            cap: 0,
            ptr: NonNull::dangling(),
            _marker: PhantomData,
        }
    }
}

impl fmt::Debug for LazyTail {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        // Don't dump the raw bytes — they're meaningless without per-tag
        // payload type information. The presence bitmap is enough to be
        // useful in logs.
        f.debug_struct("LazyTail")
            .field("present", &format_args!("{:#034b}", self.present))
            .field("len", &self.len)
            .field("cap", &self.cap)
            .finish()
    }
}

impl Drop for LazyTail {
    fn drop(&mut self) {
        // Per-tag payload drops have been performed by `TaskStorage::drop`
        // already (it walks `self.present` and invokes the macro-generated
        // drop dispatch). Here we only deallocate the byte buffer.
        if self.cap > 0 {
            // SAFETY: We allocated `cap` bytes at `ptr` with align
            // `TAIL_BUFFER_ALIGN`. The same layout deallocates correctly.
            unsafe {
                dealloc(
                    self.ptr.as_ptr(),
                    Layout::from_size_align_unchecked(self.cap as usize, TAIL_BUFFER_ALIGN),
                );
            }
        }
    }
}

impl ShrinkToFit for LazyTail {
    fn shrink_to_fit(&mut self) {
        if self.cap == 0 || self.cap == self.len {
            return;
        }
        // Reallocate to exactly fit `len` bytes. `mimalloc_good_size`-aware
        // shrink lives a layer above; this is the minimum-footprint variant.
        unsafe {
            if self.len == 0 {
                dealloc(
                    self.ptr.as_ptr(),
                    Layout::from_size_align_unchecked(self.cap as usize, TAIL_BUFFER_ALIGN),
                );
                self.ptr = NonNull::dangling();
                self.cap = 0;
            } else {
                let new_layout =
                    Layout::from_size_align_unchecked(self.len as usize, TAIL_BUFFER_ALIGN);
                let new_ptr = std::alloc::realloc(
                    self.ptr.as_ptr(),
                    Layout::from_size_align_unchecked(self.cap as usize, TAIL_BUFFER_ALIGN),
                    self.len as usize,
                );
                if new_ptr.is_null() {
                    handle_alloc_error(new_layout);
                }
                self.ptr = NonNull::new_unchecked(new_ptr);
                self.cap = self.len;
            }
        }
    }
}

impl LazyTail {
    /// Compute the byte offset of the payload for `tag`, assuming the
    /// `present` bitmap is consistent with `len`. Returns `Some(offset)` if
    /// `tag` is currently present, else `None`.
    ///
    /// The offset is the sum of `padded_size[k]` over all set bits `k`
    /// strictly below the bit for `tag` in `present`.
    #[inline]
    pub(crate) fn offset_of(&self, tag: u8, padded_size: &[u16]) -> Option<usize> {
        let bit = 1u32 << (tag - 1);
        if self.present & bit == 0 {
            return None;
        }
        let mask_below = self.present & (bit - 1);
        Some(Self::sum_padded_sizes(mask_below, padded_size))
    }

    /// Sum of padded sizes for every set bit in `mask`.
    #[inline]
    pub(crate) fn sum_padded_sizes(mut mask: u32, padded_size: &[u16]) -> usize {
        let mut offset = 0usize;
        while mask != 0 {
            let bit_idx = mask.trailing_zeros();
            // `bit_idx` is in 0..32; tag is `bit_idx + 1`, in 1..=LAZY_N.
            offset += padded_size[bit_idx as usize + 1] as usize;
            mask &= mask - 1;
        }
        offset
    }

    /// `true` iff the variant with `tag` has a payload in the tail.
    #[inline]
    pub(crate) fn has(&self, tag: u8) -> bool {
        self.present & (1u32 << (tag - 1)) != 0
    }

    /// Get a typed reference to the payload for `tag`.
    ///
    /// # Safety
    /// `T` must be the exact payload type for `tag` per the schema's
    /// `LAZY_SIZE` / `LAZY_ALIGN` tables. `padded_size` must be the schema's
    /// `LAZY_PADDED_SIZE` table.
    #[inline]
    pub(crate) unsafe fn find<T>(&self, tag: u8, padded_size: &[u16]) -> Option<&T> {
        let offset = self.offset_of(tag, padded_size)?;
        // SAFETY: `offset` is within `len <= cap`, so `ptr.add(offset)` is
        // inside the allocation. The bytes at that offset were written as a
        // `T` by `install`; we trust the caller's `T` matches the tag.
        unsafe { Some(&*self.ptr.as_ptr().add(offset).cast::<T>()) }
    }

    /// Get a typed mutable reference to the payload for `tag`.
    ///
    /// # Safety
    /// Same as [`Self::find`].
    #[inline]
    pub(crate) unsafe fn find_mut<T>(&mut self, tag: u8, padded_size: &[u16]) -> Option<&mut T> {
        let offset = self.offset_of(tag, padded_size)?;
        // SAFETY: see `find`. `&mut self` gives us exclusive access.
        unsafe { Some(&mut *self.ptr.as_ptr().add(offset).cast::<T>()) }
    }

    /// Install a payload for `tag`. Panics if the tag is already present.
    ///
    /// Grows the tail buffer if necessary. Caller must ensure `T` matches.
    ///
    /// # Safety
    /// `T` must match the payload type for `tag` per the schema tables.
    pub(crate) unsafe fn install<T>(&mut self, tag: u8, value: T, padded_size: &[u16]) {
        debug_assert!(!self.has(tag), "lazy variant tag {tag} already present");
        let bit = 1u32 << (tag - 1);
        let mask_below = self.present & (bit - 1);
        let mask_at_or_above = self.present & !mask_below;
        let payload_size = padded_size[tag as usize] as usize;
        let offset = Self::sum_padded_sizes(mask_below, padded_size);
        let above_bytes = Self::sum_padded_sizes(mask_at_or_above, padded_size);
        let new_len = self.len as usize + payload_size;

        if new_len > self.cap as usize {
            // SAFETY: `grow_to` allocates / reallocates the buffer to fit
            // `new_len` bytes; `len` and `cap` are updated to reflect the
            // new allocation. After the call `self.ptr` is valid for at
            // least `new_len` bytes.
            unsafe { self.grow_to(new_len) };
        }

        // SAFETY: We've ensured capacity for `new_len` bytes. Shift any
        // already-present payloads above `offset` to make room for the new
        // payload, then write it.
        unsafe {
            let base = self.ptr.as_ptr();
            if above_bytes > 0 {
                // memmove the tail above the insert point right by `payload_size`.
                std::ptr::copy(
                    base.add(offset),
                    base.add(offset + payload_size),
                    above_bytes,
                );
            }
            std::ptr::write(base.add(offset).cast::<T>(), value);
        }

        self.len = new_len as u16;
        self.present |= bit;
    }

    /// Take a payload for `tag`, removing it. Returns `None` if not present.
    ///
    /// # Safety
    /// `T` must match the payload type for `tag`.
    pub(crate) unsafe fn take<T>(&mut self, tag: u8, padded_size: &[u16]) -> Option<T> {
        let offset = self.offset_of(tag, padded_size)?;
        let bit = 1u32 << (tag - 1);
        let payload_size = padded_size[tag as usize] as usize;
        let mask_above = self.present & !((bit << 1) - 1);
        let above_bytes = Self::sum_padded_sizes(mask_above, padded_size);

        // SAFETY: `offset` is valid; we read the payload as `T` (caller
        // ensures the type matches), then memmove the bytes above `offset +
        // payload_size` left by `payload_size`, then shrink `len`.
        let value = unsafe {
            let base = self.ptr.as_ptr();
            let value = std::ptr::read(base.add(offset).cast::<T>());
            if above_bytes > 0 {
                std::ptr::copy(
                    base.add(offset + payload_size),
                    base.add(offset),
                    above_bytes,
                );
            }
            value
        };

        self.len -= payload_size as u16;
        self.present &= !bit;
        Some(value)
    }

    /// Replace the payload for `tag` with `value`. Returns the old payload
    /// if present; otherwise installs the new payload and returns `None`.
    ///
    /// # Safety
    /// `T` must match the payload type for `tag`.
    pub(crate) unsafe fn replace<T>(
        &mut self,
        tag: u8,
        value: T,
        padded_size: &[u16],
    ) -> Option<T> {
        if let Some(offset) = self.offset_of(tag, padded_size) {
            // Same-tag replace: payload size is fixed by the type, so we can
            // overwrite in place without shifting anything else.
            // SAFETY: caller ensures `T` matches `tag`.
            let old = unsafe {
                let ptr = self.ptr.as_ptr().add(offset).cast::<T>();
                let old = std::ptr::read(ptr);
                std::ptr::write(ptr, value);
                old
            };
            Some(old)
        } else {
            // SAFETY: caller ensures `T` matches `tag`.
            unsafe { self.install(tag, value, padded_size) };
            None
        }
    }

    /// Grow the buffer so it can hold at least `min_bytes`.
    ///
    /// # Safety
    /// Caller holds `&mut self`; no outstanding references into the buffer.
    unsafe fn grow_to(&mut self, min_bytes: usize) {
        debug_assert!(min_bytes > self.cap as usize);
        // Double-then-round: start at 64 B for the first allocation, then
        // grow by powers of two. Cap at `u16::MAX` (~64 KB) which is far
        // above any realistic working set.
        let mut new_cap = if self.cap == 0 {
            64usize
        } else {
            (self.cap as usize) * 2
        };
        while new_cap < min_bytes {
            new_cap = new_cap.saturating_mul(2);
        }
        let new_cap = new_cap.min(u16::MAX as usize);
        assert!(
            new_cap >= min_bytes,
            "lazy tail capacity overflow: requested {min_bytes}, max {}",
            u16::MAX,
        );

        // SAFETY: `TAIL_BUFFER_ALIGN` is a valid alignment (power of two,
        // ≤ usize::MAX). `new_cap` fits in a `Layout`.
        let new_layout = unsafe { Layout::from_size_align_unchecked(new_cap, TAIL_BUFFER_ALIGN) };
        let new_ptr = if self.cap == 0 {
            // SAFETY: `alloc(layout)` with non-zero size is sound.
            unsafe { alloc(new_layout) }
        } else {
            // SAFETY: existing allocation has size `self.cap` with the same
            // alignment, so `realloc` from that layout is sound.
            let old_layout =
                unsafe { Layout::from_size_align_unchecked(self.cap as usize, TAIL_BUFFER_ALIGN) };
            unsafe { std::alloc::realloc(self.ptr.as_ptr(), old_layout, new_cap) }
        };
        if new_ptr.is_null() {
            handle_alloc_error(new_layout);
        }
        // SAFETY: alloc/realloc returns a non-null pointer to `new_cap` bytes.
        self.ptr = unsafe { NonNull::new_unchecked(new_ptr) };
        self.cap = new_cap as u16;
    }
}
